export default {
  async fetch(request, env) {
    const url = new URL(request.url);

    // First-party APIs: analytics (D1 binding DB + DASH_PASSWORD secret)
    // and newsletter (RESEND_API_KEY secret).
    if (url.pathname.startsWith('/api/')) {
      return (await handleApi(request, env))
        || (await handleNewsletterApi(request, env))
        || nlJson(request, 404, { error: 'not found' });
    }

    const path = url.pathname.replace(/\/$/, '') || '/';
    const search = url.search;

    // 0. Normalize .html suffixes to clean URLs (Pagefind result URLs and
    //    old direct links point at the raw static files, which only exist
    //    under /blog/<slug>.html and would otherwise 404 after the prefix
    //    strip below).
    if (path.endsWith('.html')) {
      const clean = path.slice(0, -5).replace(/\/index$/, '') || '/';
      return Response.redirect(url.origin + clean + search, 301);
    }

    // Blog-hostname-only URL shape: on blog.kubesimplify.com the blog lives
    // at / and /blog/* strips its prefix. On localhost / *.pages.dev previews
    // the full export serves as-is (/ = main homepage, /blog = blog index),
    // so the whole site can be reviewed from one dev server.
    const isBlogHost = url.hostname === 'blog.kubesimplify.com';

    // 1. Strip /blog/ prefix FIRST — before asset detection. Otherwise
    //    /blog/rss.xml looks like an asset, gets a 404 (no file at that path),
    //    and the Next.js 404 page's JS loops back to /blog/rss.xml.
    if (isBlogHost && path === '/blog') {
      return Response.redirect(url.origin + '/' + search, 301);
    }
    if (isBlogHost && path.startsWith('/blog/')) {
      const rest = path.slice(5); // remove '/blog'
      return Response.redirect(url.origin + rest + search, 301);
    }

    // 2. Assets: serve as-is, no rewrite
    if (
      path.startsWith('/_next/') ||
      path.startsWith('/img/') ||
      path === '/sitemap.xml' ||
      path === '/rss.xml' ||
      path === '/atom.xml' ||
      path === '/robots.txt' ||
      path === '/llms.txt' ||
      path === '/favicon.ico' ||
      /\.[a-zA-Z0-9]+$/.test(path)
    ) {
      return env.ASSETS.fetch(request);
    }

    // 3. Main-site routes don't belong on the blog subdomain. Only on the
    //    real blog hostname — local dev and *.pages.dev previews serve the
    //    full static export and should show these pages themselves.
    if (
      url.hostname === 'blog.kubesimplify.com' &&
      (KUBESIMPLIFY_ROUTES.has(path) || KUBESIMPLIFY_PREFIXES.some((p) => path.startsWith(p)))
    ) {
      return Response.redirect('https://kubesimplify.com' + path + search, 301);
    }

    // Community shortlink (temporary redirect: invite links can rotate)
    if (path === '/discord') {
      return Response.redirect('https://discord.gg/26Z384WSPB', 302);
    }

    // 4. Legacy index → /
    if (path === '/blogs') {
      return Response.redirect(url.origin + '/' + search, 301);
    }

    // / → serve /blog content (URL stays /), blog hostname only
    if (isBlogHost && path === '/') {
      return env.ASSETS.fetch(new Request(url.origin + '/blog' + search, request));
    }

    // Known blog sub-routes: rewrite to /blog/<...>
    const slugCandidate = path.slice(1); // strip leading /
    if (
      BLOG_SLUGS.has(slugCandidate) ||
      path === '/authors' ||
      path === '/write' ||
      path.startsWith('/authors/') ||
      path.startsWith('/tag/') ||
      path.startsWith('/author/') ||
      path.startsWith('/hub/') ||
      path.startsWith('/page/') ||
      path === '/series' ||
      path.startsWith('/series/')
    ) {
      return env.ASSETS.fetch(new Request(url.origin + '/blog' + path + search, request));
    }

    // Anything else: try static lookup (Pages will 404 if missing)
    return env.ASSETS.fetch(request);
  }
};
